/// <summary>
/// Register the new methods for category field in SalesAgreement form.
/// </summary>
public void init()
{         
    next init();
    FormDataSource aLine_ds = this.dataSource(formDataSourceStr(SalesAgreement, ALine));
    FormDataObject formDataObject = aLine_ds.object(fieldNum(AgreementLine, Category));

    aLine_ds.object(fieldNum(AgreementLine, Category)).registerOverrideMethod(methodStr(formDataObject, lookupReference), formMethodStr(SalesAgreement, METOverridenCategoryLookupReference));
    aLine_ds.object(fieldNum(AgreementLine, Category)).registerOverrideMethod(methodStr(formDataObject, resolveReference), formMethodStr(SalesAgreement, METOverridenResolveReference));
}

/// <summary>
/// Override the lookupReference method for Category field.
/// If the default commitment is vendor category value commitment the category lookup should use the supplemental retail hierarchy.
/// Otherwise, it should use the sales category hierarchy as per standard.
/// </summary>
/// <param name = "_formReferenceControl">Category form reference control</param>
/// <returns><c>Common</c></returns>
public Common METOverridenCategoryLookupReference(FormReferenceControl _formReferenceControl)
{
    AgreementLine agreementLine = this.dataSource(formDataSourceStr(SalesAgreement, ALine)).cursor();

    return EcoResCategory::lookupCategoryHierarchyRole(_formReferenceControl,
                                                       agreementLine.METNamedCategoryHierarchyRole());
}

/// <summary>
/// Override the resolveReference method for Category field.
/// If the default commitment is vendor category value commitment the category lookup should use the supplemental retail hierarchy.
/// Otherwise, it should use the sales category hierarchy as per standard.
/// </summary>
/// <param name = "_formReferenceControl">Category form reference control</param>
/// <returns><c>Common</c></returns>
public Common METOverridenResolveReference(FormReferenceControl _formReferenceControl)
{
    AgreementLine agreementLine = this.dataSource(formDataSourceStr(SalesAgreement, ALine)).cursor();

    return EcoResCategory::resolveCategoryHierarchyRole(_formReferenceControl,
                                                        agreementLine.METNamedCategoryHierarchyRole());    
}
